using Captovix;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
internal static class Program
{
 [STAThread]static int Main(){try{int n=0;void Check(bool value,string message){if(!value)throw new Exception(message);n++;Console.WriteLine("PASS: "+message);}var app=new App();app.InitializeComponent();app.ShutdownMode=ShutdownMode.OnExplicitShutdown;app.Resources["TransparencyGrid"]=Brushes.LightGray;
 var original=Enumerable.Repeat((byte)255,400*300*4).ToArray();var bitmap=ImageTransfer.Bitmap(400,300,original);var doc=new EditorDocument{OriginalWidth=400,OriginalHeight=300};var surface=new EditorSurface();surface.Load(bitmap,new EditorSession(doc));surface.SetZoom(1);surface.Measure(new Size(1000,1000));surface.Arrange(new Rect(0,0,surface.Width,surface.Height));var preview=new RenderTargetBitmap((int)surface.Width,(int)surface.Height,96,96,PixelFormats.Pbgra32);preview.Render(surface);var bytes=ImageTransfer.Bgra(preview);Check(bytes[(5*preview.PixelWidth+5)*4+3]==0,"Empty interaction gutter has no checkerboard or opaque frame");Check(bytes[((int)EditorSurface.WorkspacePad*preview.PixelWidth+(int)EditorSurface.WorkspacePad+1)*4+3]==255,"Captured image remains visible inside its own pixel rectangle");Check(ImageTransfer.Bgra(surface.Flatten()).SequenceEqual(original),"Unedited capture exports exact original pixels and size");
 var callout=new Annotation{Kind=AnnotationKind.Callout,CalloutStyle=CalloutStyle.RoundedSpeech,CalloutBodyPivot=true,X1=80,Y1=-80,X2=280,Y2=10,TailX=130,TailY=30,Text="Ghi chú",FontSize=20,TextPadding=30,FillEnabled=true,Stroke=2};var outsideDoc=new EditorDocument{OriginalWidth=400,OriginalHeight=300,Appearance=new(){DrawOutsideImage=true},Annotations=[callout]};var session=new EditorSession(outsideDoc);surface.Load(bitmap,session);surface.SelectIds([callout.Id]);var content=EditorRenderer.ContentBounds(callout);session.Change(_=>surface.FitSelectionCanvas());Check(session.Document.Appearance.ExtendTop==(int)Math.Ceiling(-content.Top)&&session.Document.Appearance.ExtendLeft==0&&session.Document.Appearance.ExtendRight==0&&session.Document.Appearance.ExtendBottom==0,"Callout above image adds exactly its rendered top bounds");Check(surface.Flatten().PixelWidth==400,"Top-only callout never creates a horizontal border");session.Undo();Check(session.Document.Appearance.ExtendTop==0,"Object and canvas growth share an Undo transaction");
 var flags=BindingFlags.NonPublic|BindingFlags.Instance;var window=new MainWindow();var editor=(EditorSurface)window.FindName("Surface");var textBox=(TextBox)window.FindName("InlineText");var a=new Annotation{Kind=AnnotationKind.Callout,CalloutStyle=CalloutStyle.RoundedSpeech,CalloutBodyPivot=true,X1=50,Y1=60,X2=270,Y2=180,TailX=80,TailY=210,Text="Ghi chú",FontSize=20,TextPadding=30,FillEnabled=true};var editingSession=new EditorSession(new(){OriginalWidth=400,OriginalHeight=300,Annotations=[a]});typeof(MainWindow).GetField("_session",flags)!.SetValue(window,editingSession);editor.Load(bitmap,editingSession);editor.SelectIds([a.Id]);typeof(MainWindow).GetMethod("SyncProperties",flags)!.Invoke(window,null);void Invoke(string method,params object[] args)=>typeof(MainWindow).GetMethod(method,flags)!.Invoke(window,args);
 Invoke("BeginInlineText");Check(textBox.Background is SolidColorBrush brush&&brush.Color.A==0&&textBox.BorderThickness==new Thickness(0),"Direct text entry has a transparent background and zero border");Check(editor.InlineEditingId==a.Id,"Only the editor suppresses duplicate rendered glyphs");textBox.Text="Sửa trực tiếp\nTiếng Việt rõ nét";Check(editingSession.Document.Annotations[0].Text==textBox.Text&&editingSession.InTransaction&&!editingSession.Dirty,"Vietnamese live draft stays in one unsaved transaction");var during=EditorRenderer.Render(bitmap,editingSession.Document);var noText=editingSession.Document.Clone();noText.Annotations[0].Text="";Check(!ImageTransfer.Bgra(during).SequenceEqual(ImageTransfer.Bgra(EditorRenderer.Render(bitmap,noText))),"Editor-only suppression never hides text in export");Invoke("EndInlineText",true);Check(editingSession.CanUndo&&editor.InlineEditingId==null&&editor.Tool==EditorTool.Select,"Click-away commit exits text tool and enables Undo");editingSession.Undo();Check(editingSession.Document.Annotations[0].Text=="Ghi chú","One Undo restores pre-edit text and body");editingSession.Redo();Invoke("BeginInlineText");textBox.Text="Không lưu nội dung này";Invoke("EndInlineText",false);Check(editingSession.Document.Annotations[0].Text=="Sửa trực tiếp\nTiếng Việt rõ nét","Escape cancels the entire live draft");
 foreach(var kind in Enum.GetValues<CalloutStyle>()){var sample=new Annotation{Kind=AnnotationKind.Callout,CalloutStyle=kind,X1=40,Y1=40,X2=80,Y2=80,FontSize=28,TextPadding=30,Text="Tiếng Việt"};EditorRenderer.FitText(sample,new(0,0,400,300));Check(EditorRenderer.TextContent(sample).Width>=100&&sample.X1==40&&sample.Y1==40,"Text auto-fit preserves anchor and readable inset: "+kind);}
 foreach(double angle in new[]{0d,35d,90d}){var pinned=new Annotation{Kind=AnnotationKind.Callout,CalloutStyle=CalloutStyle.RoundedSpeech,CalloutBodyPivot=true,X1=60,Y1=50,X2=280,Y2=160,TailX=100,TailY=200,Rotation=angle,Text="Một",FontSize=20,TextPadding=30};var target=EditorRenderer.WorldPoint(pinned,new Point(pinned.TailX,pinned.TailY));pinned.Text=string.Join("\n",Enumerable.Repeat("Nội dung dài",8));EditorRenderer.FitText(pinned,new(0,0,400,300),true);var after=EditorRenderer.WorldPoint(pinned,new Point(pinned.TailX,pinned.TailY));Check((after-target).Length<.0001,"Auto-fit keeps the free tail target in world space at rotation "+angle);}
 window.Close();Console.WriteLine($"{n} text refinement Windows checks passed. Live IME, taskbar, DPI and visual acceptance are still required.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
